def answer(self, expression):
    """
    Check if a given mathematical expression using the cards can evaluate to 24.
    :param expression: string, mathematical expression using the cards
    :return: bool, True if the expression evaluates to 24, False otherwise
    >>> game = TwentyFourPointGame()
    >>> game.nums = [4, 3, 6, 6]
    >>> ans = "4*3+6+6"
    >>> ret = game.answer(ans)
    True
    """
    if not self.nums:
        self.get_my_cards()

    # Extract numbers from the expression and verify they are from self.nums
    try:
        import ast
        parsed = ast.parse(expression)
        expr_nums = []
        for node in ast.walk(parsed):
            if isinstance(node, (ast.Constant, ast.Num)):
                expr_nums.append(node.value)

        # Check all numbers in expression come from available cards
        for num in expr_nums:
            if num not in self.nums:
                return False

        # Evaluate expression and check if result is 24
        return self.evaluate_expression(expression)
    except:
        return False
